  padding: 4px 20px;
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 600;
}
.pricing-card__name { font-size: 1.25rem; font-weight: 700; color: var(--navy); margin-bottom: 8px; }
.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.75rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1;
  margin-bottom: 4px;
}
.pricing-card__price span { font-size: 1rem; font-weight: 500; color: var(--gray-500); }
.pricing-card__desc { font-size: .875rem; color: var(--gray-500); margin-bottom: 24px; }
.pricing-card__features { flex: 1; margin-bottom: 32px; }
.pricing-card__features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 0;
  font-size: .9375rem;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
}
.pricing-card__features li:last-child { border-bottom: none; }
.pricing-card__features svg { flex-shrink: 0; margin-top: 2px; }
.check-icon { color: var(--success); }
.dash-icon { color: var(--gray-300); }
.pricing-card .btn { width: 100%; }

/* ---------- FAQ ---------- */
.faq-list { max-width: 740px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 22px 0;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-question svg {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
  color: var(--gray-400);
}
.faq-item.open .faq-question svg { transform: rotate(180deg); color: var(--primary); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .35s cubic-bezier(.4,0,.2,1), padding .35s;
  padding: 0 0;
}
.faq-item.open .faq-answer { max-height: 200px; padding: 0 0 22px; }
.faq-answer p { font-size: .9375rem; color: var(--gray-600); max-width: none; }

/* ---------- CTA Section ---------- */
.cta-section {
  background: linear-gradient(135deg, var(--navy) 0%, #162B4A 50%, #1A3358 100%);
  padding: 96px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-section::before {
  content: '';
  position: absolute;
  top: -80px;
  right: -100px;
  width: 350px;
  height: 350px;
  background: radial-gradient(circle, rgba(222,80,82,.15) 0%, transparent 70%);
  border-radius: 50%;
}
.cta-section h2 { color: var(--white); max-width: 600px; margin: 0 auto 16px; }
.cta-section p { color: rgba(255,255,255,.75); margin: 0 auto 36px; }

/* ---------- Contact Form ---------- */
.contact-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 56px; align-items: start; }
.form-group { margin-bottom: 20px; }
.form-group label {
  display: block;
  font-size: .875rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 6px;
}
.form-group label .required { color: var(--accent); }
.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: 12px 16px;
  font-size: .9375rem;
  font-family: var(--font-body);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), box-shadow var(--transition);
  background: var(--white);
  color: var(--gray-800);
}
.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0,81,195,.12);
}
.form-group textarea { resize: vertical; min-height: 120px; }
.form-group input.error,
.form-group textarea.error { border-color: var(--accent); }
.form-error { font-size: .8125rem; color: var(--accent); margin-top: 4px; display: none; }
.form-group input.error + .form-error,
.form-group textarea.error + .form-error { display: block; }
.form-success {
  display: none;
  background: #ECFDF5;
  border: 1px solid #A7F3D0;
  border-radius: var(--radius-sm);
  padding: 24px;
  text-align: center;
}
.form-success.show { display: block; }
.form-success svg { color: var(--success); width: 48px; height: 48px; margin: 0 auto 12px; }
.form-success h3 { color: #065F46; margin-bottom: 6px; }
.form-success p { color: #047857; margin: 0 auto; font-size: .9375rem; }

/* ---------- Office Locations ---------- */
.office-card {
  background: var(--off-white);
  border-radius: var(--radius);
  padding: 28px;
  border: 1px solid var(--gray-200);
}
.office-card h4 { margin-bottom: 8px; }
.office-card p { font-size: .9375rem; }
.office-card__label {
  font-size: .75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--primary);
  margin-bottom: 4px;
}

/* ---------- Team ---------- */
.team-card { text-align: center; }
.team-card__avatar {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), #3B82F6);
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.5rem;
  font-weight: 700;
}
.team-card h3 { margin-bottom: 4px; font-size: 1.125rem; }
.team-card p { font-size: .875rem; color: var(--gray-500); margin: 0 auto; }

/* ---------- Integrations ---------- */
.integration-category { margin-bottom: 40px; }
.integration-category h3 { margin-bottom: 16px; }
.integration-logos { display: flex; flex-wrap: wrap; gap: 16px; }
.integration-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 100px;
  font-size: .9375rem;
  font-weight: 500;
  transition: all var(--transition);
}
.integration-chip:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-sm);
}

/* ---------- Feature Detail (features page) ---------- */
.feature-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; padding: 80px 0; }
.feature-detail:nth-child(even) .feature-detail__content { order: -1; }
.feature-detail__visual {
  background: var(--off-white);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--gray-200);
}
.feature-detail__visual svg { width: 80px; height: 80px; color: var(--primary); opacity: .4; }
.feature-detail__content h2 { margin-bottom: 16px; }
.feature-detail__content p { margin-bottom: 24px; }
.feature-detail__list { margin-top: 16px; }
.feature-detail__list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 12px;
  font-size: .9375rem;
  color: var(--gray-700);
}
.feature-detail__list svg { flex-shrink: 0; color: var(--success); margin-top: 2px; }

/* ---------- Mission ---------- */
.mission-content { max-width: 720px; margin: 0 auto; text-align: center; }
.mission-content p { margin: 0 auto 20px; font-size: 1.125rem; }

/* ---------- Footer ---------- */
.footer { background: var(--navy); color: rgba(255,255,255,.7); padding: 64px 0 32px; }
.footer__grid { display: grid; grid-template-columns: 1.5fr repeat(4, 1fr); gap: 40px; margin-bottom: 48px; }
.footer__brand { }
.footer__brand-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.footer__brand p { font-size: .875rem; max-width: 280px; }
.footer__col h4 { color: var(--white); font-size: .8125rem; text-transform: uppercase; letter-spacing: .08em; margin-bottom: 16px; }
.footer__col a { display: block; font-size: .875rem; padding: 5px 0; transition: color var(--transition); }
.footer__col a:hover { color: var(--white); }
.footer__bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: .8125rem;
}
.footer__social { display: flex; gap: 16px; }
.footer__social a { opacity: .6; transition: opacity var(--transition); }
.footer__social a:hover { opacity: 1; }

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .steps { grid-template-columns: repeat(2, 1fr); }
  .pricing-grid { grid-template-columns: 1fr; max-width: 420px; }
  .pricing-card--featured { transform: none; }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .feature-detail { grid-template-columns: 1fr; gap: 40px; }
  .feature-detail:nth-child(even) .feature-detail__content { order: 0; }
  .contact-grid { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .header__nav { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }
  .hero { padding: 120px 0 64px; }
  .hero--home { padding: 120px 0 80px; }
  .hero--page { padding: 120px 0 48px; }
  .stats__grid { grid-template-columns: repeat(2, 1fr); }
  .grid-2 { grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr; }
  .steps { grid-template-columns: 1fr; gap: 24px; }
  .footer__grid { grid-template-columns: 1fr; gap: 32px; }
  .footer__bottom { flex-direction: column; gap: 12px; text-align: center; }
}
@media (max-width: 480px) {
  .hero__actions { flex-direction: column; }
  .hero__actions .btn { width: 100%; }
  .stats__grid { grid-template-columns: 1fr; }
}

/* ---------- Animations ---------- */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes countUp {
  from { opacity: 0; transform: scale(.9); }
  to { opacity: 1; transform: scale(1); }
}
.animate-in { animation: fadeInUp .6s ease forwards; }
.animate-delay-1 { animation-delay: .1s; }
.animate-delay-2 { animation-delay: .2s; }
.animate-delay-3 { animation-delay: .3s; }
.animate-delay-4 { animation-delay: .4s; }
