/* =========================================================
   ShiftWise — Global Styles
   Brand: #0F1B2D (navy), #0051C3 (primary), #DE5052 (accent)
   ========================================================= */

/* ---------- Reset & Base ---------- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0F1B2D;
  --primary: #0051C3;
  --primary-dark: #003E96;
  --accent: #DE5052;
  --accent-dark: #C43E40;
  --white: #FFFFFF;
  --off-white: #F6F8FB;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --success: #10B981;
  --font-heading: 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,.1);
  --shadow-xl: 0 20px 48px rgba(0,0,0,.12);
  --radius: 12px;
  --radius-sm: 8px;
  --radius-lg: 16px;
  --transition: .25s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* ---------- Typography ---------- */
h1, h2, h3, h4 { font-family: var(--font-heading); font-weight: 700; color: var(--navy); line-height: 1.15; }
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); letter-spacing: -.02em; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); letter-spacing: -.015em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }
p { color: var(--gray-600); max-width: 640px; }
.text-sm { font-size: .875rem; }
.text-lg { font-size: 1.125rem; line-height: 1.7; }

/* ---------- Layout ---------- */
.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 96px 0; }
.section--gray { background: var(--off-white); }
.section--navy { background: var(--navy); color: var(--white); }
.section--navy h2, .section--navy h3, .section--navy h4 { color: var(--white); }
.section--navy p { color: rgba(255,255,255,.75); }

.grid { display: grid; gap: 32px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

.flex { display: flex; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 32px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: var(--white);
  box-shadow: 0 4px 14px rgba(222,80,82,.35);
}
.btn-primary:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(222,80,82,.4);
}
.btn-secondary {
  background: transparent;
  color: var(--primary);
  border: 2px solid var(--primary);
}
.btn-secondary:hover {
  background: var(--primary);
  color: var(--white);
  transform: translateY(-2px);
}
.btn-white {
  background: var(--white);
  color: var(--navy);
  box-shadow: var(--shadow-md);
}
.btn-white:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}
.btn-ghost {
  background: rgba(255,255,255,.15);
  color: var(--white);
  border: 1px solid rgba(255,255,255,.3);
}
.btn-ghost:hover {
  background: rgba(255,255,255,.25);
}
.btn-sm { padding: 10px 24px; font-size: .875rem; }
.btn-lg { padding: 18px 40px; font-size: 1.125rem; }

/* ---------- Header / Nav ---------- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,0,0,.06);
  transition: all var(--transition);
}
.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -.02em;
}
.header__logo svg { flex-shrink: 0; }
.header__nav { display: flex; align-items: center; gap: 36px; }
.header__link {
  font-size: .9375rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: color var(--transition);
  position: relative;
}
.header__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--primary);
  transition: width var(--transition);
}
.header__link:hover, .header__link.active { color: var(--navy); }
.header__link:hover::after, .header__link.active::after { width: 100%; }
.header__cta { margin-left: 12px; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 28px;
  height: 28px;
  cursor: pointer;
  z-index: 1001;
}
.hamburger span {
  display: block;
  width: 100%;
  height: 2.5px;
  background: var(--navy);
  border-radius: 2px;
  transition: all var(--transition);
}
.hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

/* Mobile Nav Drawer */
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  height: 100vh;
  background: var(--white);
  z-index: 999;
  padding: 96px 32px 32px;
  box-shadow: var(--shadow-xl);
  transition: right .35s cubic-bezier(.4,0,.2,1);
  flex-direction: column;
  gap: 8px;
}
.mobile-nav.open { right: 0; }
.mobile-nav a {
  display: block;
  padding: 14px 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
  transition: color var(--transition);
}
.mobile-nav a:hover { color: var(--primary); }
.mobile-nav .btn { margin-top: 16px; width: 100%; text-align: center; }
.overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.4);
  z-index: 998;
  opacity: 0;
  transition: opacity .35s;
}
.overlay.open { opacity: 1; }

/* ---------- Hero ---------- */
.hero {
  padding: 160px 0 96px;
  position: relative;
  overflow: hidden;
}
.hero--home {
  background: linear-gradient(135deg, var(--navy) 0%, #162B4A 50%, #1A3358 100%);
  color: var(--white);
  padding: 160px 0 120px;
}
.hero--home h1 { color: var(--white); max-width: 720px; }
.hero--home p { color: rgba(255,255,255,.8); max-width: 560px; }
.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 500;
  color: rgba(255,255,255,.9);
  margin-bottom: 24px;
}
.hero__badge svg { width: 14px; height: 14px; }
.hero__actions { display: flex; gap: 16px; margin-top: 36px; flex-wrap: wrap; }
.hero--page {
  background: var(--off-white);
  padding: 140px 0 60px;
  text-align: center;
}
.hero--page p { margin: 12px auto 0; }

/* Decorative blobs */
.hero--home::before {
  content: '';
  position: absolute;
  top: -120px;
  right: -160px;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(222,80,82,.2) 0%, transparent 70%);
  border-radius: 50%;
}
.hero--home::after {
  content: '';
  position: absolute;
  bottom: -80px;
  left: -120px;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(0,81,195,.15) 0%, transparent 70%);
  border-radius: 50%;
}

/* ---------- Stats ---------- */
.stats { padding: 72px 0; background: var(--white); border-top: 1px solid var(--gray-100); border-bottom: 1px solid var(--gray-100); }
.stats__grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; text-align: center; }
.stat__number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 800;
  color: var(--primary);
  line-height: 1.1;
}
.stat__label { font-size: .9375rem; color: var(--gray-500); margin-top: 6px; }

/* ---------- Features ---------- */
.feature-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 36px;
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.feature-card__icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary), #3B82F6);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--white);
}
.feature-card__icon svg { width: 28px; height: 28px; }
.feature-card h3 { margin-bottom: 10px; }
.feature-card p { font-size: .9375rem; }

/* ---------- How It Works ---------- */
.steps { counter-reset: step; display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; margin-top: 56px; }
.step { position: relative; text-align: center; padding: 0 8px; }
.step__number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--primary);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}
.step h3 { margin-bottom: 10px; }
.step p { font-size: .9375rem; margin: 0 auto; }
.step__connector {
  display: none;
  position: absolute;
  top: 28px;
  left: calc(50% + 36px);
  width: calc(100% - 72px);
  height: 2px;
  background: var(--gray-200);
}

/* ---------- Testimonials ---------- */
.testimonial-carousel { position: relative; max-width: 720px; margin: 0 auto; overflow: hidden; }
.testimonial-track { display: flex; transition: transform .5s cubic-bezier(.4,0,.2,1); }
.testimonial-slide { min-width: 100%; padding: 0 24px; }
.testimonial-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 40px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
  text-align: center;
}
.testimonial-card__stars { color: #F59E0B; font-size: 1.25rem; margin-bottom: 16px; letter-spacing: 4px; }
.testimonial-card blockquote {
  font-size: 1.125rem;
  font-style: italic;
  color: var(--gray-700);
  line-height: 1.7;
  margin-bottom: 24px;
  max-width: none;
}
.testimonial-card__author { font-weight: 600; color: var(--navy); }
.testimonial-card__role { font-size: .875rem; color: var(--gray-500); margin-top: 2px; }
.carousel-controls { display: flex; justify-content: center; gap: 16px; margin-top: 32px; }
.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  color: var(--gray-600);
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); }
.carousel-dots { display: flex; gap: 8px; justify-content: center; margin-top: 20px; }
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-dot.active { background: var(--primary); width: 28px; border-radius: 5px; }

/* ---------- Pricing ---------- */
.billing-toggle {
  display: inline-flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 56px;
  font-weight: 500;
}
.billing-toggle__label { color: var(--gray-500); transition: color var(--transition); }
.billing-toggle__label.active { color: var(--navy); font-weight: 600; }
.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 14px;
  cursor: pointer;
  transition: background var(--transition);
}
.toggle-switch.active { background: var(--primary); }
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}
.toggle-switch.active::after { transform: translateX(24px); }
.save-badge {
  background: #ECFDF5;
  color: #059669;
  padding: 4px 12px;
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 600;
}

.pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; max-width: 1000px; margin: 0 auto; }
.pricing-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 40px 32px;
  border: 2px solid var(--gray-200);
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}
.pricing-card:hover { border-color: var(--gray-300); }
.pricing-card--featured {
  border-color: var(--primary);
  position: relative;
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}
.pricing-card--featured:hover { border-color: var(--primary); }
.pricing-card__popular {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 20px;
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 600;
}
.pricing-card__name { font-size: 1.25rem; font-weight: 700; color: var(--navy); margin-bottom: 8px; }
.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.75rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1;
  margin-bottom: 4px;
}
.pricing-card__price span { font-size: 1rem; font-weight: 500; color: var(--gray-500); }
.pricing-card__desc { font-size: .875rem; color: var(--gray-500); margin-bottom: 24px; }
.pricing-card__features { flex: 1; margin-bottom: 32px; }
.pricing-card__features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 0;
  font-size: .9375rem;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
}
.pricing-card__features li:last-child { border-bottom: none; }
.pricing-card__features svg { flex-shrink: 0; margin-top: 2px; }
.check-icon { color: var(--success); }
.dash-icon { color: var(--gray-300); }
.pricing-card .btn { width: 100%; }

/* ---------- FAQ ---------- */
.faq-list { max-width: 740px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 22px 0;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-question svg {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
  color: var(--gray-400);
}
.faq-item.open .faq-question svg { transform: rotate(180deg); color: var(--primary); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .35s cubic-bezier(.4,0,.2,1), padding .35s;
  padding: 0 0;
}
.faq-item.open .faq-answer { max-height: 200px; padding: 0 0 22px; }
.faq-answer p { font-size: .9375rem; color: var(--gray-600); max-width: none; }

/* ---------- CTA Section ---------- */
.cta-section {
  background: linear-gradient(135deg, var(--navy) 0%, #162B4A 50%, #1A3358 100%);
  padding: 96px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-section::before {
  content: '';
  position: absolute;
  top: -80px;
  right: -100px;
  width: 350px;
  height: 350px;
  background: radial-gradient(circle, rgba(222,80,82,.15) 0%, transparent 70%);
  border-radius: 50%;
}
.cta-section h2 { color: var(--white); max-width: 600px; margin: 0 auto 16px; }
.cta-section p { color: rgba(255,255,255,.75); margin: 0 auto 36px; }

/* ---------- Contact Form ---------- */
.contact-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 56px; align-items: start; }
.form-group { margin-bottom: 20px; }
.form-group label {
  display: block;
  font-size: .875rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 6px;
}
.form-group label .required { color: var(--accent); }
.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: 12px 16px;
  font-size: .9375rem;
  font-family: var(--font-body);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), box-shadow var(--transition);
  background: var(--white);
  color: var(--gray-800);
}
.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0,81,195,.12);
}
.form-group textarea { resize: vertical; min-height: 120px; }
.form-group input.error,
.form-group textarea.error { border-color: var(--accent); }
.form-error { font-size: .8125rem; color: var(--accent); margin-top: 4px; display: none; }
.form-group input.error + .form-error,
.form-group textarea.error + .form-error { display: block; }
.form-success {
  display: none;
  background: #ECFDF5;
  border: 1px solid #A7F3D0;
  border-radius: var(--radius-sm);
  padding: 24px;
  text-align: center;
}
.form-success.show { display: block; }
.form-success svg { color: var(--success); width: 48px; height: 48px; margin: 0 auto 12px; }
.form-success h3 { color: #065F46; margin-bottom: 6px; }
.form-success p { color: #047857; margin: 0 auto; font-size: .9375rem; }

/* ---------- Office Locations ---------- */
.office-card {
  background: var(--off-white);
  border-radius: var(--radius);
  padding: 28px;
  border: 1px solid var(--gray-200);
}
.office-card h4 { margin-bottom: 8px; }
.office-card p { font-size: .9375rem; }
.office-card__label {
  font-size: .75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--primary);
  margin-bottom: 4px;
}

/* ---------- Team ---------- */
.team-card { text-align: center; }
.team-card__avatar {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), #3B82F6);
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.5rem;
  font-weight: 700;
}
.team-card h3 { margin-bottom: 4px; font-size: 1.125rem; }
.team-card p { font-size: .875rem; color: var(--gray-500); margin: 0 auto; }

/* ---------- Integrations ---------- */
.integration-category { margin-bottom: 40px; }
.integration-category h3 { margin-bottom: 16px; }
.integration-logos { display: flex; flex-wrap: wrap; gap: 16px; }
.integration-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 100px;
  font-size: .9375rem;
  font-weight: 500;
  transition: all var(--transition);
}
.integration-chip:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-sm);
}

/* ---------- Feature Detail (features page) ---------- */
.feature-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; padding: 80px 0; }
.feature-detail:nth-child(even) .feature-detail__content { order: -1; }
.feature-detail__visual {
  background: var(--off-white);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--gray-200);
}
.feature-detail__visual svg { width: 80px; height: 80px; color: var(--primary); opacity: .4; }
.feature-detail__content h2 { margin-bottom: 16px; }
.feature-detail__content p { margin-bottom: 24px; }
.feature-detail__list { margin-top: 16px; }
.feature-detail__list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 12px;
  font-size: .9375rem;
  color: var(--gray-700);
}
.feature-detail__list svg { flex-shrink: 0; color: var(--success); margin-top: 2px; }

/* ---------- Mission ---------- */
.mission-content { max-width: 720px; margin: 0 auto; text-align: center; }
.mission-content p { margin: 0 auto 20px; font-size: 1.125rem; }

/* ---------- Footer ---------- */
.footer { background: var(--navy); color: rgba(255,255,255,.7); padding: 64px 0 32px; }
.footer__grid { display: grid; grid-template-columns: 1.5fr repeat(4, 1fr); gap: 40px; margin-bottom: 48px; }
.footer__brand { }
.footer__brand-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.footer__brand p { font-size: .875rem; max-width: 280px; }
.footer__col h4 { color: var(--white); font-size: .8125rem; text-transform: uppercase; letter-spacing: .08em; margin-bottom: 16px; }
.footer__col a { display: block; font-size: .875rem; padding: 5px 0; transition: color var(--transition); }
.footer__col a:hover { color: var(--white); }
.footer__bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: .8125rem;
}
.footer__social { display: flex; gap: 16px; }
.footer__social a { opacity: .6; transition: opacity var(--transition); }
.footer__social a:hover { opacity: 1; }

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .steps { grid-template-columns: repeat(2, 1fr); }
  .pricing-grid { grid-template-columns: 1fr; max-width: 420px; }
  .pricing-card--featured { transform: none; }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .feature-detail { grid-template-columns: 1fr; gap: 40px; }
  .feature-detail:nth-child(even) .feature-detail__content { order: 0; }
  .contact-grid { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .header__nav { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }
  .hero { padding: 120px 0 64px; }
  .hero--home { padding: 120px 0 80px; }
  .hero--page { padding: 120px 0 48px; }
  .stats__grid { grid-template-columns: repeat(2, 1fr); }
  .grid-2 { grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr; }
  .steps { grid-template-columns: 1fr; gap: 24px; }
  .footer__grid { grid-template-columns: 1fr; gap: 32px; }
  .footer__bottom { flex-direction: column; gap: 12px; text-align: center; }
}
@media (max-width: 480px) {
  .hero__actions { flex-direction: column; }
  .hero__actions .btn { width: 100%; }
  .stats__grid { grid-template-columns: 1fr; }
}

/* ---------- Animations ---------- */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes countUp {
  from { opacity: 0; transform: scale(.9); }
  to { opacity: 1; transform: scale(1); }
}
.animate-in { animation: fadeInUp .6s ease forwards; }
.animate-delay-1 { animation-delay: .1s; }
.animate-delay-2 { animation-delay: .2s; }
.animate-delay-3 { animation-delay: .3s; }
.animate-delay-4 { animation-delay: .4s; }

/* =========================================================
   ShiftWise — Global Styles
   Brand: #0F1B2D (navy), #0051C3 (primary), #DE5052 (accent)
   ========================================================= */

/* ---------- Reset & Base ---------- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0F1B2D;
  --primary: #0051C3;
  --primary-dark: #003E96;
  --accent: #DE5052;
  --accent-dark: #C43E40;
  --white: #FFFFFF;
  --off-white: #F6F8FB;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --success: #10B981;
  --font-heading: 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,.1);
  --shadow-xl: 0 20px 48px rgba(0,0,0,.12);
  --radius: 12px;
  --radius-sm: 8px;
  --radius-lg: 16px;
  --transition: .25s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* ---------- Typography ---------- */
h1, h2, h3, h4 { font-family: var(--font-heading); font-weight: 700; color: var(--navy); line-height: 1.15; }
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); letter-spacing: -.02em; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); letter-spacing: -.015em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }
p { color: var(--gray-600); max-width: 640px; }
.text-sm { font-size: .875rem; }
.text-lg { font-size: 1.125rem; line-height: 1.7; }

/* ---------- Layout ---------- */
.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 96px 0; }
.section--gray { background: var(--off-white); }
.section--navy { background: var(--navy); color: var(--white); }
.section--navy h2, .section--navy h3, .section--navy h4 { color: var(--white); }
.section--navy p { color: rgba(255,255,255,.75); }

.grid { display: grid; gap: 32px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

.flex { display: flex; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 32px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: var(--white);
  box-shadow: 0 4px 14px rgba(222,80,82,.35);
}
.btn-primary:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(222,80,82,.4);
}
.btn-secondary {
  background: transparent;
  color: var(--primary);
  border: 2px solid var(--primary);
}
.btn-secondary:hover {
  background: var(--primary);
  color: var(--white);
  transform: translateY(-2px);
}
.btn-white {
  background: var(--white);
  color: var(--navy);
  box-shadow: var(--shadow-md);
}
.btn-white:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}
.btn-ghost {
  background: rgba(255,255,255,.15);
  color: var(--white);
  border: 1px solid rgba(255,255,255,.3);
}
.btn-ghost:hover {
  background: rgba(255,255,255,.25);
}
.btn-sm { padding: 10px 24px; font-size: .875rem; }
.btn-lg { padding: 18px 40px; font-size: 1.125rem; }

/* ---------- Header / Nav ---------- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,0,0,.06);
  transition: all var(--transition);
}
.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -.02em;
}
.header__logo svg { flex-shrink: 0; }
.header__nav { display: flex; align-items: center; gap: 36px; }
.header__link {
  font-size: .9375rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: color var(--transition);
  position: relative;
}
.header__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--primary);
  transition: width var(--transition);
}
.header__link:hover, .header__link.active { color: var(--navy); }
.header__link:hover::after, .header__link.active::after { width: 100%; }
.header__cta { margin-left: 12px; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 28px;
  height: 28px;
  cursor: pointer;
  z-index: 1001;
}
.hamburger span {
  display: block;
  width: 100%;
  height: 2.5px;
  background: var(--navy);
  border-radius: 2px;
  transition: all var(--transition);
}
.hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

/* Mobile Nav Drawer */
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  height: 100vh;
  background: var(--white);
  z-index: 999;
  padding: 96px 32px 32px;
  box-shadow: var(--shadow-xl);
  transition: right .35s cubic-bezier(.4,0,.2,1);
  flex-direction: column;
  gap: 8px;
}
.mobile-nav.open { right: 0; }
.mobile-nav a {
  display: block;
  padding: 14px 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
  transition: color var(--transition);
}
.mobile-nav a:hover { color: var(--primary); }
.mobile-nav .btn { margin-top: 16px; width: 100%; text-align: center; }
.overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.4);
  z-index: 998;
  opacity: 0;
  transition: opacity .35s;
}
.overlay.open { opacity: 1; }

/* ---------- Hero ---------- */
.hero {
  padding: 160px 0 96px;
  position: relative;
  overflow: hidden;
}
.hero--home {
  background: linear-gradient(135deg, var(--navy) 0%, #162B4A 50%, #1A3358 100%);
  color: var(--white);
  padding: 160px 0 120px;
}
.hero--home h1 { color: var(--white); max-width: 720px; }
.hero--home p { color: rgba(255,255,255,.8); max-width: 560px; }
.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 500;
  color: rgba(255,255,255,.9);
  margin-bottom: 24px;
}
.hero__badge svg { width: 14px; height: 14px; }
.hero__actions { display: flex; gap: 16px; margin-top: 36px; flex-wrap: wrap; }
.hero--page {
  background: var(--off-white);
  padding: 140px 0 60px;
  text-align: center;
}
.hero--page p { margin: 12px auto 0; }

/* Decorative blobs */
.hero--home::before {
  content: '';
  position: absolute;
  top: -120px;
  right: -160px;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(222,80,82,.2) 0%, transparent 70%);
  border-radius: 50%;
}
.hero--home::after {
  content: '';
  position: absolute;
  bottom: -80px;
  left: -120px;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(0,81,195,.15) 0%, transparent 70%);
  border-radius: 50%;
}

/* ---------- Stats ---------- */
.stats { padding: 72px 0; background: var(--white); border-top: 1px solid var(--gray-100); border-bottom: 1px solid var(--gray-100); }
.stats__grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; text-align: center; }
.stat__number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 800;
  color: var(--primary);
  line-height: 1.1;
}
.stat__label { font-size: .9375rem; color: var(--gray-500); margin-top: 6px; }

/* ---------- Features ---------- */
.feature-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 36px;
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.feature-card__icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary), #3B82F6);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--white);
}
.feature-card__icon svg { width: 28px; height: 28px; }
.feature-card h3 { margin-bottom: 10px; }
.feature-card p { font-size: .9375rem; }

/* ---------- How It Works ---------- */
.steps { counter-reset: step; display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; margin-top: 56px; }
.step { position: relative; text-align: center; padding: 0 8px; }
.step__number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--primary);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}
.step h3 { margin-bottom: 10px; }
.step p { font-size: .9375rem; margin: 0 auto; }
.step__connector {
  display: none;
  position: absolute;
  top: 28px;
  left: calc(50% + 36px);
  width: calc(100% - 72px);
  height: 2px;
  background: var(--gray-200);
}

/* ---------- Testimonials ---------- */
.testimonial-carousel { position: relative; max-width: 720px; margin: 0 auto; overflow: hidden; }
.testimonial-track { display: flex; transition: transform .5s cubic-bezier(.4,0,.2,1); }
.testimonial-slide { min-width: 100%; padding: 0 24px; }
.testimonial-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 40px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
  text-align: center;
}
.testimonial-card__stars { color: #F59E0B; font-size: 1.25rem; margin-bottom: 16px; letter-spacing: 4px; }
.testimonial-card blockquote {
  font-size: 1.125rem;
  font-style: italic;
  color: var(--gray-700);
  line-height: 1.7;
  margin-bottom: 24px;
  max-width: none;
}
.testimonial-card__author { font-weight: 600; color: var(--navy); }
.testimonial-card__role { font-size: .875rem; color: var(--gray-500); margin-top: 2px; }
.carousel-controls { display: flex; justify-content: center; gap: 16px; margin-top: 32px; }
.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  color: var(--gray-600);
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); }
.carousel-dots { display: flex; gap: 8px; justify-content: center; margin-top: 20px; }
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-dot.active { background: var(--primary); width: 28px; border-radius: 5px; }

/* ---------- Pricing ---------- */
.billing-toggle {
  display: inline-flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 56px;
  font-weight: 500;
}
.billing-toggle__label { color: var(--gray-500); transition: color var(--transition); }
.billing-toggle__label.active { color: var(--navy); font-weight: 600; }
.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 14px;
  cursor: pointer;
  transition: background var(--transition);
}
.toggle-switch.active { background: var(--primary); }
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}
.toggle-switch.active::after { transform: translateX(24px); }
.save-badge {
  background: #ECFDF5;
  color: #059669;
  padding: 4px 12px;
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 600;
}

.pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; max-width: 1000px; margin: 0 auto; }
.pricing-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 40px 32px;
  border: 2px solid var(--gray-200);
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}
.pricing-card:hover { border-color: var(--gray-300); }
.pricing-card--featured {
  border-color: var(--primary);
  position: relative;
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}
.pricing-card--featured:hover { border-color: var(--primary); }
.pricing-card__popular {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 20px;
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 600;
}
.pricing-card__name { font-size: 1.25rem; font-weight: 700; color: var(--navy); margin-bottom: 8px; }
.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.75rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1;
  margin-bottom: 4px;
}
.pricing-card__price span { font-size: 1rem; font-weight: 500; color: var(--gray-500); }
.pricing-card__desc { font-size: .875rem; color: var(--gray-500); margin-bottom: 24px; }
.pricing-card__features { flex: 1; margin-bottom: 32px; }
.pricing-card__features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 0;
  font-size: .9375rem;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
}
.pricing-card__features li:last-child { border-bottom: none; }
.pricing-card__features svg { flex-shrink: 0; margin-top: 2px; }
.check-icon { color: var(--success); }
.dash-icon { color: var(--gray-300); }
.pricing-card .btn { width: 100%; }

/* ---------- FAQ ---------- */
.faq-list { max-width: 740px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 22px 0;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-question svg {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
  color: var(--gray-400);
}
.faq-item.open .faq-question svg { transform: rotate(180deg); color: var(--primary); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .35s cubic-bezier(.4,0,.2,1), padding .35s;
  padding: 0 0;
}
.faq-item.open .faq-answer { max-height: 200px; padding: 0 0 22px; }
.faq-answer p { font-size: .9375rem; color: var(--gray-600); max-width: none; }

/* ---------- CTA Section ---------- */
.cta-section {
  background: linear-gradient(135deg, var(--navy) 0%, #162B4A 50%, #1A3358 100%);
  padding: 96px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-section::before {
  content: '';
  position: absolute;
  top: -80px;
  right: -100px;
  width: 350px;
  height: 350px;
  background: radial-gradient(circle, rgba(222,80,82,.15) 0%, transparent 70%);
  border-radius: 50%;
}
.cta-section h2 { color: var(--white); max-width: 600px; margin: 0 auto 16px; }
.cta-section p { color: rgba(255,255,255,.75); margin: 0 auto 36px; }

/* ---------- Contact Form ---------- */
.contact-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 56px; align-items: start; }
.form-group { margin-bottom: 20px; }
.form-group label {
  display: block;
  font-size: .875rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 6px;
}
.form-group label .required { color: var(--accent); }
.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: 12px 16px;
  font-size: .9375rem;
  font-family: var(--font-body);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), box-shadow var(--transition);
  background: var(--white);
  color: var(--gray-800);
}
.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0,81,195,.12);
}
.form-group textarea { resize: vertical; min-height: 120px; }
.form-group input.error,
.form-group textarea.error { border-color: var(--accent); }
.form-error { font-size: .8125rem; color: var(--accent); margin-top: 4px; display: none; }
.form-group input.error + .form-error,
.form-group textarea.error + .form-error { display: block; }
.form-success {
  display: none;
  background: #ECFDF5;
  border: 1px solid #A7F3D0;
  border-radius: var(--radius-sm);
  padding: 24px;
  text-align: center;
}
.form-success.show { display: block; }
.form-success svg { color: var(--success); width: 48px; height: 48px; margin: 0 auto 12px; }
.form-success h3 { color: #065F46; margin-bottom: 6px; }
.form-success p { color: #047857; margin: 0 auto; font-size: .9375rem; }

/* ---------- Office Locations ---------- */
.office-card {
  background: var(--off-white);
  border-radius: var(--radius);
  padding: 28px;
  border: 1px solid var(--gray-200);
}
.office-card h4 { margin-bottom: 8px; }
.office-card p { font-size: .9375rem; }
.office-card__label {
  font-size: .75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--primary);
  margin-bottom: 4px;
}

/* ---------- Team ---------- */
.team-card { text-align: center; }
.team-card__avatar {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), #3B82F6);
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.5rem;
  font-weight: 700;
}
.team-card h3 { margin-bottom: 4px; font-size: 1.125rem; }
.team-card p { font-size: .875rem; color: var(--gray-500); margin: 0 auto; }

/* ---------- Integrations ---------- */
.integration-category { margin-bottom: 40px; }
.integration-category h3 { margin-bottom: 16px; }
.integration-logos { display: flex; flex-wrap: wrap; gap: 16px; }
.integration-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 100px;
  font-size: .9375rem;
  font-weight: 500;
  transition: all var(--transition);
}
.integration-chip:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-sm);
}

/* ---------- Feature Detail (features page) ---------- */
.feature-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; padding: 80px 0; }
.feature-detail:nth-child(even) .feature-detail__content { order: -1; }
.feature-detail__visual {
  background: var(--off-white);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--gray-200);
}
.feature-detail__visual svg { width: 80px; height: 80px; color: var(--primary); opacity: .4; }
.feature-detail__content h2 { margin-bottom: 16px; }
.feature-detail__content p { margin-bottom: 24px; }
.feature-detail__list { margin-top: 16px; }
.feature-detail__list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 12px;
  font-size: .9375rem;
  color: var(--gray-700);
}
.feature-detail__list svg { flex-shrink: 0; color: var(--success); margin-top: 2px; }

/* ---------- Mission ---------- */
.mission-content { max-width: 720px; margin: 0 auto; text-align: center; }
.mission-content p { margin: 0 auto 20px; font-size: 1.125rem; }

/* ---------- Footer ---------- */
.footer { background: var(--navy); color: rgba(255,255,255,.7); padding: 64px 0 32px; }
.footer__grid { display: grid; grid-template-columns: 1.5fr repeat(4, 1fr); gap: 40px; margin-bottom: 48px; }
.footer__brand { }
.footer__brand-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.footer__brand p { font-size: .875rem; max-width: 280px; }
.footer__col h4 { color: var(--white); font-size: .8125rem; text-transform: uppercase; letter-spacing: .08em; margin-bottom: 16px; }
.footer__col a { display: block; font-size: .875rem; padding: 5px 0; transition: color var(--transition); }
.footer__col a:hover { color: var(--white); }
.footer__bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: .8125rem;
}
.footer__social { display: flex; gap: 16px; }
.footer__social a { opacity: .6; transition: opacity var(--transition); }
.footer__social a:hover { opacity: 1; }

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .steps { grid-template-columns: repeat(2, 1fr); }
  .pricing-grid { grid-template-columns: 1fr; max-width: 420px; }
  .pricing-card--featured { transform: none; }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .feature-detail { grid-template-columns: 1fr; gap: 40px; }
  .feature-detail:nth-child(even) .feature-detail__content { order: 0; }
  .contact-grid { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .header__nav { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }
  .hero { padding: 120px 0 64px; }
  .hero--home { padding: 120px 0 80px; }
  .hero--page { padding: 120px 0 48px; }
  .stats__grid { grid-template-columns: repeat(2, 1fr); }
  .grid-2 { grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr; }
  .steps { grid-template-columns: 1fr; gap: 24px; }
  .footer__grid { grid-template-columns: 1fr; gap: 32px; }
  .footer__bottom { flex-direction: column; gap: 12px; text-align: center; }
}
@media (max-width: 480px) {
  .hero__actions { flex-direction: column; }
  .hero__actions .btn { width: 100%; }
  .stats__grid { grid-template-columns: 1fr; }
}

/* ---------- Animations ---------- */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes countUp {
  from { opacity: 0; transform: scale(.9); }
  to { opacity: 1; transform: scale(1); }
}
.animate-in { animation: fadeInUp .6s ease forwards; }
.animate-delay-1 { animation-delay: .1s; }
.animate-delay-2 { animation-delay: .2s; }
.animate-delay-3 { animation-delay: .3s; }
.animate-delay-4 { animation-delay: .4s; }

raw_arguments.content:
/* =========================================================
   ShiftWise — Global Styles
   Brand: #0F1B2D (navy), #0051C3 (primary), #DE5052 (accent)
   ========================================================= */

/* ---------- Reset & Base ---------- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0F1B2D;
  --primary: #0051C3;
  --primary-dark: #003E96;
  --accent: #DE5052;
  --accent-dark: #C43E40;
  --white: #FFFFFF;
  --off-white: #F6F8FB;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --success: #10B981;
  --font-heading: 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,.1);
  --shadow-xl: 0 20px 48px rgba(0,0,0,.12);
  --radius: 12px;
  --radius-sm: 8px;
  --radius-lg: 16px;
  --transition: .25s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* ---------- Typography ---------- */
h1, h2, h3, h4 { font-family: var(--font-heading); font-weight: 700; color: var(--navy); line-height: 1.15; }
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); letter-spacing: -.02em; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); letter-spacing: -.015em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }
p { color: var(--gray-600); max-width: 640px; }
.text-sm { font-size: .875rem; }
.text-lg { font-size: 1.125rem; line-height: 1.7; }

/* ---------- Layout ---------- */
.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 96px 0; }
.section--gray { background: var(--off-white); }
.section--navy { background: var(--navy); color: var(--white); }
.section--navy h2, .section--navy h3, .section--navy h4 { color: var(--white); }
.section--navy p { color: rgba(255,255,255,.75); }

.grid { display: grid; gap: 32px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

.flex { display: flex; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 32px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: var(--white);
  box-shadow: 0 4px 14px rgba(222,80,82,.35);
}
.btn-primary:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(222,80,82,.4);
}
.btn-secondary {
  background: transparent;
  color: var(--primary);
  border: 2px solid var(--primary);
}
.btn-secondary:hover {
  background: var(--primary);
  color: var(--white);
  transform: translateY(-2px);
}
.btn-white {
  background: var(--white);
  color: var(--navy);
  box-shadow: var(--shadow-md);
}
.btn-white:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}
.btn-ghost {
  background: rgba(255,255,255,.15);
  color: var(--white);
  border: 1px solid rgba(255,255,255,.3);
}
.btn-ghost:hover {
  background: rgba(255,255,255,.25);
}
.btn-sm { padding: 10px 24px; font-size: .875rem; }
.btn-lg { padding: 18px 40px; font-size: 1.125rem; }

/* ---------- Header / Nav ---------- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,0,0,.06);
  transition: all var(--transition);
}
.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -.02em;
}
.header__logo svg { flex-shrink: 0; }
.header__nav { display: flex; align-items: center; gap: 36px; }
.header__link {
  font-size: .9375rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: color var(--transition);
  position: relative;
}
.header__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--primary);
  transition: width var(--transition);
}
.header__link:hover, .header__link.active { color: var(--navy); }
.header__link:hover::after, .header__link.active::after { width: 100%; }
.header__cta { margin-left: 12px; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 28px;
  height: 28px;
  cursor: pointer;
  z-index: 1001;
}
.hamburger span {
  display: block;
  width: 100%;
  height: 2.5px;
  background: var(--navy);
  border-radius: 2px;
  transition: all var(--transition);
}
.hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

/* Mobile Nav Drawer */
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  height: 100vh;
  background: var(--white);
  z-index: 999;
  padding: 96px 32px 32px;
  box-shadow: var(--shadow-xl);
  transition: right .35s cubic-bezier(.4,0,.2,1);
  flex-direction: column;
  gap: 8px;
}
.mobile-nav.open { right: 0; }
.mobile-nav a {
  display: block;
  padding: 14px 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
  transition: color var(--transition);
}
.mobile-nav a:hover { color: var(--primary); }
.mobile-nav .btn { margin-top: 16px; width: 100%; text-align: center; }
.overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.4);
  z-index: 998;
  opacity: 0;
  transition: opacity .35s;
}
.overlay.open { opacity: 1; }

/* ---------- Hero ---------- */
.hero {
  padding: 160px 0 96px;
  position: relative;
  overflow: hidden;
}
.hero--home {
  background: linear-gradient(135deg, var(--navy) 0%, #162B4A 50%, #1A3358 100%);
  color: var(--white);
  padding: 160px 0 120px;
}
.hero--home h1 { color: var(--white); max-width: 720px; }
.hero--home p { color: rgba(255,255,255,.8); max-width: 560px; }
.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 500;
  color: rgba(255,255,255,.9);
  margin-bottom: 24px;
}
.hero__badge svg { width: 14px; height: 14px; }
.hero__actions { display: flex; gap: 16px; margin-top: 36px; flex-wrap: wrap; }
.hero--page {
  background: var(--off-white);
  padding: 140px 0 60px;
  text-align: center;
}
.hero--page p { margin: 12px auto 0; }

/* Decorative blobs */
.hero--home::before {
  content: '';
  position: absolute;
  top: -120px;
  right: -160px;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(222,80,82,.2) 0%, transparent 70%);
  border-radius: 50%;
}
.hero--home::after {
  content: '';
  position: absolute;
  bottom: -80px;
  left: -120px;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(0,81,195,.15) 0%, transparent 70%);
  border-radius: 50%;
}

/* ---------- Stats ---------- */
.stats { padding: 72px 0; background: var(--white); border-top: 1px solid var(--gray-100); border-bottom: 1px solid var(--gray-100); }
.stats__grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; text-align: center; }
.stat__number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 800;
  color: var(--primary);
  line-height: 1.1;
}
.stat__label { font-size: .9375rem; color: var(--gray-500); margin-top: 6px; }

/* ---------- Features ---------- */
.feature-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 36px;
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.feature-card__icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary), #3B82F6);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--white);
}
.feature-card__icon svg { width: 28px; height: 28px; }
.feature-card h3 { margin-bottom: 10px; }
.feature-card p { font-size: .9375rem; }

/* ---------- How It Works ---------- */
.steps { counter-reset: step; display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; margin-top: 56px; }
.step { position: relative; text-align: center; padding: 0 8px; }
.step__number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--primary);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}
.step h3 { margin-bottom: 10px; }
.step p { font-size: .9375rem; margin: 0 auto; }
.step__connector {
  display: none;
  position: absolute;
  top: 28px;
  left: calc(50% + 36px);
  width: calc(100% - 72px);
  height: 2px;
  background: var(--gray-200);
}

/* ---------- Testimonials ---------- */
.testimonial-carousel { position: relative; max-width: 720px; margin: 0 auto; overflow: hidden; }
.testimonial-track { display: flex; transition: transform .5s cubic-bezier(.4,0,.2,1); }
.testimonial-slide { min-width: 100%; padding: 0 24px; }
.testimonial-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 40px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
  text-align: center;
}
.testimonial-card__stars { color: #F59E0B; font-size: 1.25rem; margin-bottom: 16px; letter-spacing: 4px; }
.testimonial-card blockquote {
  font-size: 1.125rem;
  font-style: italic;
  color: var(--gray-700);
  line-height: 1.7;
  margin-bottom: 24px;
  max-width: none;
}
.testimonial-card__author { font-weight: 600; color: var(--navy); }
.testimonial-card__role { font-size: .875rem; color: var(--gray-500); margin-top: 2px; }
.carousel-controls { display: flex; justify-content: center; gap: 16px; margin-top: 32px; }
.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  color: var(--gray-600);
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); }
.carousel-dots { display: flex; gap: 8px; justify-content: center; margin-top: 20px; }
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-dot.active { background: var(--primary); width: 28px; border-radius: 5px; }

/* ---------- Pricing ---------- */
.billing-toggle {
  display: inline-flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 56px;
  font-weight: 500;
}
.billing-toggle__label { color: var(--gray-500); transition: color var(--transition); }
.billing-toggle__label.active { color: var(--navy); font-weight: 600; }
.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 14px;
  cursor: pointer;
  transition: background var(--transition);
}
.toggle-switch.active { background: var(--primary); }
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}
.toggle-switch.active::after { transform: translateX(24px); }
.save-badge {
  background: #ECFDF5;
  color: #059669;
  padding: 4px 12px;
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 600;
}

.pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; max-width: 1000px; margin: 0 auto; }
.pricing-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 40px 32px;
  border: 2px solid var(--gray-200);
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}
.pricing-card:hover { border-color: var(--gray-300); }
.pricing-card--featured {
  border-color: var(--primary);
  position: relative;
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}
.pricing-card--featured:hover { border-color: var(--primary); }
.pricing-card__popular {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 20px;
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 600;
}
.pricing-card__name { font-size: 1.25rem; font-weight: 700; color: var(--navy); margin-bottom: 8px; }
.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.75rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1;
  margin-bottom: 4px;
}
.pricing-card__price span { font-size: 1rem; font-weight: 500; color: var(--gray-500); }
.pricing-card__desc { font-size: .875rem; color: var(--gray-500); margin-bottom: 24px; }
.pricing-card__features { flex: 1; margin-bottom: 32px; }
.pricing-card__features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 0;
  font-size: .9375rem;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
}
.pricing-card__features li:last-child { border-bottom: none; }
.pricing-card__features svg { flex-shrink: 0; margin-top: 2px; }
.check-icon { color: var(--success); }
.dash-icon { color: var(--gray-300); }
.pricing-card .btn { width: 100%; }

/* ---------- FAQ ---------- */
.faq-list { max-width: 740px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 22px 0;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-question svg {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
  color: var(--gray-400);
}
.faq-item.open .faq-question svg { transform: rotate(180deg); color: var(--primary); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .35s cubic-bezier(.4,0,.2,1), padding .35s;
  padding: 0 0;
}
.faq-item.open .faq-answer { max-height: 200px; padding: 0 0 22px; }
.faq-answer p { font-size: .9375rem; color: var(--gray-600); max-width: none; }

/* ---------- CTA Section ---------- */
.cta-section {
  background: linear-gradient(135deg, var(--navy) 0%, #162B4A 50%, #1A3358 100%);
  padding: 96px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-section::before {
  content: '';
  position: absolute;
  top: -80px;
  right: -100px;
  width: 350px;
  height: 350px;
  background: radial-gradient(circle, rgba(222,80,82,.15) 0%, transparent 70%);
  border-radius: 50%;
}
.cta-section h2 { color: var(--white); max-width: 600px; margin: 0 auto 16px; }
.cta-section p { color: rgba(255,255,255,.75); margin: 0 auto 36px; }

/* ---------- Contact Form ---------- */
.contact-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 56px; align-items: start; }
.form-group { margin-bottom: 20px; }
.form-group label {
  display: block;
  font-size: .875rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 6px;
}
.form-group label .required { color: var(--accent); }
.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: 12px 16px;
  font-size: .9375rem;
  font-family: var(--font-body);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), box-shadow var(--transition);
  background: var(--white);
  color: var(--gray-800);
}
.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0,81,195,.12);
}
.form-group textarea { resize: vertical; min-height: 120px; }
.form-group input.error,
.form-group textarea.error { border-color: var(--accent); }
.form-error { font-size: .8125rem; color: var(--accent); margin-top: 4px; display: none; }
.form-group input.error + .form-error,
.form-group textarea.error + .form-error { display: block; }
.form-success {
  display: none;
  background: #ECFDF5;
  border: 1px solid #A7F3D0;
  border-radius: var(--radius-sm);
  padding: 24px;
  text-align: center;
}
.form-success.show { display: block; }
.form-success svg { color: var(--success); width: 48px; height: 48px; margin: 0 auto 12px; }
.form-success h3 { color: #065F46; margin-bottom: 6px; }
.form-success p { color: #047857; margin: 0 auto; font-size: .9375rem; }

/* ---------- Office Locations ---------- */
.office-card {
  background: var(--off-white);
  border-radius: var(--radius);
  padding: 28px;
  border: 1px solid var(--gray-200);
}
.office-card h4 { margin-bottom: 8px; }
.office-card p { font-size: .9375rem; }
.office-card__label {
  font-size: .75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--primary);
  margin-bottom: 4px;
}

/* ---------- Team ---------- */
.team-card { text-align: center; }
.team-card__avatar {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), #3B82F6);
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.5rem;
  font-weight: 700;
}
.team-card h3 { margin-bottom: 4px; font-size: 1.125rem; }
.team-card p { font-size: .875rem; color: var(--gray-500); margin: 0 auto; }

/* ---------- Integrations ---------- */
.integration-category { margin-bottom: 40px; }
.integration-category h3 { margin-bottom: 16px; }
.integration-logos { display: flex; flex-wrap: wrap; gap: 16px; }
.integration-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 100px;
  font-size: .9375rem;
  font-weight: 500;
  transition: all var(--transition);
}
.integration-chip:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-sm);
}

/* ---------- Feature Detail (features page) ---------- */
.feature-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; padding: 80px 0; }
.feature-detail:nth-child(even) .feature-detail__content { order: -1; }
.feature-detail__visual {
  background: var(--off-white);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--gray-200);
}
.feature-detail__visual svg { width: 80px; height: 80px; color: var(--primary); opacity: .4; }
.feature-detail__content h2 { margin-bottom: 16px; }
.feature-detail__content p { margin-bottom: 24px; }
.feature-detail__list { margin-top: 16px; }
.feature-detail__list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 12px;
  font-size: .9375rem;
  color: var(--gray-700);
}
.feature-detail__list svg { flex-shrink: 0; color: var(--success); margin-top: 2px; }

/* ---------- Mission ---------- */
.mission-content { max-width: 720px; margin: 0 auto; text-align: center; }
.mission-content p { margin: 0 auto 20px; font-size: 1.125rem; }

/* ---------- Footer ---------- */
.footer { background: var(--navy); color: rgba(255,255,255,.7); padding: 64px 0 32px; }
.footer__grid { display: grid; grid-template-columns: 1.5fr repeat(4, 1fr); gap: 40px; margin-bottom: 48px; }
.footer__brand { }
.footer__brand-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.footer__brand p { font-size: .875rem; max-width: 280px; }
.footer__col h4 { color: var(--white); font-size: .8125rem; text-transform: uppercase; letter-spacing: .08em; margin-bottom: 16px; }
.footer__col a { display: block; font-size: .875rem; padding: 5px 0; transition: color var(--transition); }
.footer__col a:hover { color: var(--white); }
.footer__bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: .8125rem;
}
.footer__social { display: flex; gap: 16px; }
.footer__social a { opacity: .6; transition: opacity var(--transition); }
.footer__social a:hover { opacity: 1; }

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .steps { grid-template-columns: repeat(2, 1fr); }
  .pricing-grid { grid-template-columns: 1fr; max-width: 420px; }
  .pricing-card--featured { transform: none; }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .feature-detail { grid-template-columns: 1fr; gap: 40px; }
  .feature-detail:nth-child(even) .feature-detail__content { order: 0; }
  .contact-grid { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .header__nav { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }
  .hero { padding: 120px 0 64px; }
  .hero--home { padding: 120px 0 80px; }
  .hero--page { padding: 120px 0 48px; }
  .stats__grid { grid-template-columns: repeat(2, 1fr); }
  .grid-2 { grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr; }
  .steps { grid-template-columns: 1fr; gap: 24px; }
  .footer__grid { grid-template-columns: 1fr; gap: 32px; }
  .footer__bottom { flex-direction: column; gap: 12px; text-align: center; }
}
@media (max-width: 480px) {
  .hero__actions { flex-direction: column; }
  .hero__actions .btn { width: 100%; }
  .stats__grid { grid-template-columns: 1fr; }
}

/* ---------- Animations ---------- */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes countUp {
  from { opacity: 0; transform: scale(.9); }
  to { opacity: 1; transform: scale(1); }
}
.animate-in { animation: fadeInUp .6s ease forwards; }
.animate-delay-1 { animation-delay: .1s; }
.animate-delay-2 { animation-delay: .2s; }
.animate-delay-3 { animation-delay: .3s; }
.animate-delay-4 { animation-delay: .4s; }

